import * as THREE from 'three/webgpu';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import TSL from 'three/tsl';
import gsap from 'gsap';

const { color, uv, mix, clamp } = TSL;

export default function createNode(config, ctx) {
  const root = new THREE.Group();

  const brandMarks = [
    'HODINKEE',
    'MONOCLE',
    'WALLPAPER',
    'ESQUIRE',
    'WIRED',
    'FINANCIAL TIMES'
  ];

  const colors = {
    paper: new THREE.Color('#e8ecf2'),
    ramp0: new THREE.Color('#1a1a22'),
    ramp1: new THREE.Color('#121218')
  };

  const tileWidth = 1.0;
  const tileHeight = 0.62;
  const gap = 0.25;
  const gridStartX = -1.75;
  const gridStartY = 0.745;
  const kickerYOffset = 0.3;

  // Create kicker text
  const kickerGroup = new THREE.Group();
  kickerGroup.position.y = gridStartY + kickerYOffset;

  if (ctx.fontAtlas && typeof ctx.fontAtlas.createTextMesh === 'function') {
    const kickerMesh = ctx.fontAtlas.createTextMesh('AS FEATURED IN', {
      fontSize: 0.09,
      font: 'JetBrains Mono',
      weight: 700,
      color: colors.paper,
      opacity: 0.78,
      align: 'center'
    });
    if (kickerMesh) kickerGroup.add(kickerMesh);
  }
  root.add(kickerGroup);

  const tiles = [];
  const tileGroups = [];

  // Create 3x2 grid of tiles
  for (let row = 0; row < 2; row++) {
    for (let col = 0; col < 3; col++) {
      const index = row * 3 + col;
      const brandMark = brandMarks[index];

      const tileX = gridStartX + col * (tileWidth + gap) + tileWidth / 2;
      const tileY = gridStartY - row * (tileHeight + gap) - tileHeight / 2;

      const tileGroup = new THREE.Group();
      tileGroup.position.set(tileX, tileY, 0);

      // Create tile geometry with minimal depth for PBR
      const geometry = new THREE.BoxGeometry(tileWidth, tileHeight, 0.01, 4, 4, 1);

      // Create brushed-metal material with vertical albedo gradient
      const material = new MeshStandardNodeMaterial();
      const uvY = uv().y;
      const albedoRamp = mix(
        color(colors.ramp0),
        color(colors.ramp1),
        clamp(uvY, 0, 1)
      );

      material.colorNode = albedoRamp;
      material.roughness = 0.55;
      material.metalness = 0.5;
      material.clearcoat = 0.2;
      material.anisotropy = 0.6;
      material.anisotropyRotation = 0;

      const tileMesh = new THREE.Mesh(geometry, material);
      tileGroup.add(tileMesh);

      // Create brand mark text
      let textMesh = null;
      if (ctx.fontAtlas && typeof ctx.fontAtlas.createTextMesh === 'function') {
        textMesh = ctx.fontAtlas.createTextMesh(brandMark, {
          fontSize: 0.13,
          font: 'JetBrains Mono',
          weight: 700,
          color: colors.paper,
          opacity: 0.78,
          align: 'center'
        });

        if (textMesh) {
          textMesh.position.z = 0.01;
          tileGroup.add(textMesh);
        }
      }

      tileGroup.userData.mesh = tileMesh;
      tileGroup.userData.textMesh = textMesh;
      tileGroup.userData.brandMark = brandMark;
      tileGroup.userData.index = index;
      tileGroup.userData.isHovered = false;
      tileGroup.userData.hoverTimeline = null;

      tiles.push(tileMesh);
      tileGroups.push(tileGroup);
      root.add(tileGroup);
    }
  }

  // Hover interactions
  root.userData.handlers = {
    pointerover(event) {
      const tileMesh = event.object;
      const tileGroup = tileGroups.find(tg => tg.userData.mesh === tileMesh);

      if (tileGroup && !tileGroup.userData.isHovered) {
        tileGroup.userData.isHovered = true;

        if (tileGroup.userData.hoverTimeline) {
          tileGroup.userData.hoverTimeline.kill();
        }

        const hoverTL = gsap.timeline();

        if (tileGroup.userData.textMesh && tileGroup.userData.textMesh.material) {
          hoverTL.to(tileGroup.userData.textMesh.material, {
            opacity: 1.0,
            duration: 0.16,
            ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
          }, 0);
        }

        hoverTL.to(tileGroup.position, {
          z: 0.05,
          duration: 0.16,
          ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
        }, 0);

        tileGroup.userData.hoverTimeline = hoverTL;
      }
    },

    pointerout(event) {
      const tileMesh = event.object;
      const tileGroup = tileGroups.find(tg => tg.userData.mesh === tileMesh);

      if (tileGroup && tileGroup.userData.isHovered) {
        tileGroup.userData.isHovered = false;

        if (tileGroup.userData.hoverTimeline) {
          tileGroup.userData.hoverTimeline.kill();
        }

        const hoverTL = gsap.timeline();

        if (tileGroup.userData.textMesh && tileGroup.userData.textMesh.material) {
          hoverTL.to(tileGroup.userData.textMesh.material, {
            opacity: 0.78,
            duration: 0.16,
            ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
          }, 0);
        }

        hoverTL.to(tileGroup.position, {
          z: 0,
          duration: 0.16,
          ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
        }, 0);

        tileGroup.userData.hoverTimeline = hoverTL;
      }
    }
  };

  // Mount animation: stagger-cards with fade-up
  const mountTL = gsap.timeline();

  tileGroups.forEach((tileGroup, index) => {
    const originalY = tileGroup.position.y;
    tileGroup.position.y = originalY + 0.2;

    if (tileGroup.userData.textMesh && tileGroup.userData.textMesh.material) {
      tileGroup.userData.textMesh.material.opacity = 0;
    }

    const staggerDelay = index * 0.08;

    mountTL.to(tileGroup.position, {
      y: originalY,
      duration: 0.5,
      ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
    }, staggerDelay);

    if (tileGroup.userData.textMesh && tileGroup.userData.textMesh.material) {
      mountTL.to(tileGroup.userData.textMesh.material, {
        opacity: 0.78,
        duration: 0.5,
        ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
      }, staggerDelay);
    }
  });

  root.userData.mountTimeline = mountTL;

  // Cleanup
  root.userData.cleanup = function() {
    gsap.killTweensOf(root);
    if (root.userData.mountTimeline) {
      root.userData.mountTimeline.kill();
    }

    tileGroups.forEach(tileGroup => {
      if (tileGroup.userData.hoverTimeline) {
        tileGroup.userData.hoverTimeline.kill();
      }

      tileGroup.children.forEach(child => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) child.material.dispose();
      });
    });

    kickerGroup.children.forEach(child => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) child.material.dispose();
    });
  };

  return root;
}
